import { useState } from 'react'
import {
  BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell,
  LineChart, Line, Legend, CartesianGrid
} from 'recharts'
import { motion } from 'framer-motion'
import { GoogleGenerativeAI } from '@google/generative-ai'
import { useUser } from '../context/UserContext'
import { useCalorieData } from '../hooks/useCalorieData'
import BottomNav from '../components/BottomNav'
import WeeklyReport from '../components/WeeklyReport'
import styles from './Progress.module.css'

const genAI = new GoogleGenerativeAI(import.meta.env.VITE_GEMINI_API_KEY)

function getWeekKey() {
  const d = new Date()
  const jan1 = new Date(d.getFullYear(), 0, 1)
  const week = Math.ceil(((d - jan1) / 86400000 + jan1.getDay() + 1) / 7)
  return `${d.getFullYear()}-W${week}`
}

export default function Progress() {
  const { weeklyReport, saveWeeklyReport, calorieGoal, dietaryPreference, fitnessGoal } = useUser()
  const { weekData, bestDay, worstDay, goals } = useCalorieData()
  const [reportLoading, setReportLoading] = useState(false)
  const weekKey = getWeekKey()
  const report = weeklyReport[weekKey]

  const isSunday = new Date().getDay() === 0

  function buildMockReport() {
    const best = bestDay || weekData.find(d => d.kcal > 0) || weekData[0]
    const worst = worstDay || weekData[weekData.length - 1]
    const avgProt = Math.round(weekData.reduce((s, d) => s + d.protein, 0) / Math.max(weekData.filter(d => d.kcal > 0).length, 1))
    return {
      overview: `You've been blooming beautifully this week! Your ${best?.label || 'best day'} stood out with great calorie balance and solid macro distribution. Overall a nurturing week for your wellness journey.`,
      bestDay: { day: best?.label || '—', calories: best?.kcal || 0 },
      worstDay: { day: worst?.label || '—', calories: worst?.kcal || 0 },
      highlights: [
        'Consistent daily logging shows great commitment to your goals',
        `Strong performance on ${best?.label || 'your best day'} — great calorie balance`,
        'Keeping track of all three macros shows excellent awareness'
      ],
      improvements: [
        `Aim to keep protein above 80% of your ${goals?.protein || 50}g daily goal each day`,
        'Watch calorie intake on higher-activity days to stay within range'
      ],
      nextWeekGoal: `Focus on hitting your protein target of ${goals?.protein || 50}g daily — try adding a protein-rich snack like Greek yogurt or a handful of nuts in the afternoon.`,
      macroGaps: {
        protein: avgProt < (goals?.protein || 50) * 0.8 ? 'low' : 'good',
        carbs: 'good',
        fat: 'good'
      },
      generatedAt: new Date().toISOString()
    }
  }

  async function generateReport() {
    setReportLoading(true)
    try {
      if (!import.meta.env.VITE_GEMINI_API_KEY) {
        saveWeeklyReport(weekKey, buildMockReport())
        return
      }

      const summary = weekData
        .map(d => `${d.label}: ${d.kcal} kcal, P${d.protein}g C${d.carbs}g F${d.fat}g`)
        .join('\n')

      const reportModel = genAI.getGenerativeModel({
        model: 'gemini-2.5-flash',
        systemInstruction: [
          'You are Petal, a warm wellness coach. Return ONLY valid JSON — no markdown, no explanation.',
          'Use this exact structure:',
          '{',
          '  "overview": "2-3 sentence overall summary with one nature/flower metaphor",',
          '  "bestDay": { "day": "DayName", "calories": 1850 },',
          '  "worstDay": { "day": "DayName", "calories": 2400 },',
          '  "highlights": ["point 1", "point 2", "point 3"],',
          '  "improvements": ["point 1", "point 2"],',
          '  "nextWeekGoal": "one specific personalized goal sentence",',
          '  "macroGaps": { "protein": "low|good|high", "carbs": "low|good|high", "fat": "low|good|high" }',
          '}',
          'bestDay = day closest to calorie goal without exceeding it.',
          'worstDay = day furthest over calorie goal (or lowest calories if all under).',
          'macroGaps: compare weekly averages against goals — low if under 80%, high if over 120%.',
        ].join('\n'),
      })

      const result = await reportModel.generateContent(
        `Diet: ${dietaryPreference}, Goal: ${fitnessGoal}, Daily calorie target: ${calorieGoal} kcal\nMacro goals — Protein: ${goals?.protein}g, Carbs: ${goals?.carbs}g, Fat: ${goals?.fat}g\n\nWeek data:\n${summary}`
      )

      let parsed
      try {
        const raw = result.response.text().trim()
        const jsonStr = raw.startsWith('{') ? raw : raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1)
        parsed = JSON.parse(jsonStr)
      } catch {
        parsed = buildMockReport()
      }

      saveWeeklyReport(weekKey, { ...parsed, generatedAt: new Date().toISOString() })
    } catch {
      saveWeeklyReport(weekKey, buildMockReport())
    } finally {
      setReportLoading(false)
    }
  }

  const isStructuredReport = report && report.highlights

  const CustomTooltip = ({ active, payload, label }) => {
    if (active && payload?.length) {
      return (
        <div className={styles.tooltip}>
          <p className={styles.tooltipLabel}>{label}</p>
          <p style={{ color: 'var(--rose-dark)' }}>{payload[0].value} kcal</p>
        </div>
      )
    }
    return null
  }

  return (
    <div className={`page ${styles.progress}`}>
      <div className={styles.header}>
        <h1 className={styles.title}>Weekly Progress</h1>
        <p className={styles.sub}>Your bloom journey this week</p>
      </div>

      {/* Calorie bar chart */}
      <div className={styles.card}>
        <h3 className={styles.cardTitle}>Daily Calories</h3>
        <ResponsiveContainer width="100%" height={180}>
          <BarChart data={weekData} margin={{ top: 4, right: 0, left: -20, bottom: 0 }}>
            <XAxis dataKey="label" tick={{ fontSize: 11, fill: '#806068' }} axisLine={false} tickLine={false} />
            <YAxis tick={{ fontSize: 10, fill: '#806068' }} axisLine={false} tickLine={false} />
            <Tooltip content={<CustomTooltip />} />
            <Bar dataKey="kcal" radius={[6, 6, 0, 0]}>
              {weekData.map((d, i) => (
                <Cell key={i} fill={d.kcal <= calorieGoal ? '#f9c8d8' : '#d4607a'} />
              ))}
            </Bar>
          </BarChart>
        </ResponsiveContainer>
      </div>

      {/* Macro trend line chart */}
      <div className={styles.card}>
        <h3 className={styles.cardTitle}>Macro Trends</h3>
        <ResponsiveContainer width="100%" height={180}>
          <LineChart data={weekData} margin={{ top: 4, right: 8, left: -20, bottom: 0 }}>
            <CartesianGrid strokeDasharray="3 3" stroke="#ecdee8" />
            <XAxis dataKey="label" tick={{ fontSize: 11, fill: '#806068' }} axisLine={false} tickLine={false} />
            <YAxis tick={{ fontSize: 10, fill: '#806068' }} axisLine={false} tickLine={false} />
            <Tooltip />
            <Legend wrapperStyle={{ fontSize: 11 }} />
            <Line type="monotone" dataKey="protein" stroke="#d4607a" strokeWidth={2} dot={false} name="Protein" />
            <Line type="monotone" dataKey="carbs"   stroke="#9060c8" strokeWidth={2} dot={false} name="Carbs" />
            <Line type="monotone" dataKey="fat"     stroke="#d07030" strokeWidth={2} dot={false} name="Fat" />
          </LineChart>
        </ResponsiveContainer>
      </div>

      {/* Best / worst day */}
      <div className={styles.dayCards}>
        <div className={styles.dayCard} style={{ background: 'var(--surface-matcha)', borderColor: 'var(--matcha)' }}>
          <span className={styles.dayEmoji}>✨</span>
          <span className={styles.dayLabel}>Best day</span>
          <span className={styles.dayValue}>{bestDay?.label || '—'}</span>
          {bestDay && <span className={styles.dayKcal}>{bestDay.kcal} kcal</span>}
        </div>
        <div className={styles.dayCard} style={{ background: 'var(--surface-rose)', borderColor: 'var(--rose)' }}>
          <span className={styles.dayEmoji}>🌿</span>
          <span className={styles.dayLabel}>Most calories</span>
          <span className={styles.dayValue}>{worstDay?.label || '—'}</span>
          {worstDay && <span className={styles.dayKcal}>{worstDay.kcal} kcal</span>}
        </div>
      </div>

      {/* Weekly AI Report */}
      <div className={styles.reportSection}>
        <h3 className={styles.reportSectionTitle}>Weekly AI Report</h3>

        {isStructuredReport ? (
          <WeeklyReport
            report={report}
            weekData={weekData}
            calorieGoal={calorieGoal}
            goals={goals}
          />
        ) : report && !isStructuredReport ? (
          /* Legacy plain-text report — show old text + regenerate prompt */
          <div className={styles.reportCard}>
            <p className={styles.reportText}>{report.summary}</p>
            <p className={styles.reportMeta}>Generated {new Date(report.generatedAt).toLocaleDateString()}</p>
            <button className={styles.reportBtn} onClick={generateReport} disabled={reportLoading}>
              {reportLoading ? 'Regenerating...' : '✨ Upgrade to Full Report'}
            </button>
          </div>
        ) : (
          <div className={styles.reportCard}>
            <div className={styles.reportEmpty}>
              <p>{isSunday ? 'Generate your weekly bloom report!' : 'Available any time — keep logging to get the best insights!'}</p>
              <button
                className={styles.reportBtn}
                onClick={generateReport}
                disabled={reportLoading}
              >
                {reportLoading ? 'Generating...' : '✨ Generate Report'}
              </button>
            </div>
          </div>
        )}
      </div>

      <BottomNav />
    </div>
  )
}

import { useState } from 'react'
import {
  BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer,
  ReferenceLine, Cell
} from 'recharts'
import jsPDF from 'jspdf'
import html2canvas from 'html2canvas'
import styles from './WeeklyReport.module.css'

function getWeekRange(weekData) {
  if (!weekData || !weekData.length) return ''
  const first = new Date(weekData[0].date + 'T00:00:00')
  const last = new Date(weekData[weekData.length - 1].date + 'T00:00:00')
  const opts = { month: 'short', day: 'numeric' }
  return `${first.toLocaleDateString('en', opts)} – ${last.toLocaleDateString('en', opts)}, ${last.getFullYear()}`
}

function avg(arr) {
  const nonZero = arr.filter(v => v > 0)
  if (!nonZero.length) return 0
  return Math.round(nonZero.reduce((s, v) => s + v, 0) / nonZero.length)
}

function MacroChip({ label, average, goal, status }) {
  const color = status === 'low' ? '#d07030' : status === 'high' ? '#d4607a' : '#408040'
  const bg = status === 'low' ? '#fae0c0' : status === 'high' ? '#fad4e0' : '#d4ecc8'
  return (
    <div className={styles.macroChip} style={{ background: bg, borderColor: color + '55' }}>
      <span className={styles.macroChipLabel}>{label}</span>
      <span className={styles.macroChipValue} style={{ color }}>{average}g</span>
      <span className={styles.macroChipGoal}>goal {goal}g</span>
      <span className={styles.macroChipStatus} style={{ background: color + '22', color }}>{status || '—'}</span>
    </div>
  )
}

const ChartTooltip = ({ active, payload, label }) => {
  if (active && payload?.length) {
    return (
      <div className={styles.tooltip}>
        <p className={styles.tooltipLabel}>{label}</p>
        <p style={{ color: '#d4607a', fontWeight: 600 }}>{payload[0].value} kcal</p>
      </div>
    )
  }
  return null
}

export default function WeeklyReport({ report, weekData, calorieGoal, goals }) {
  const [pdfState, setPdfState] = useState('idle')

  const weekRange = getWeekRange(weekData)
  const avgCalories = avg(weekData.map(d => d.kcal))
  const avgProtein = avg(weekData.map(d => d.protein))
  const avgCarbs = avg(weekData.map(d => d.carbs))
  const avgFat = avg(weekData.map(d => d.fat))
  const todayStr = new Date().toLocaleDateString('en', { year: 'numeric', month: 'long', day: 'numeric' })

  const downloadPDF = async () => {
    setPdfState('loading')
    try {
      const reportEl = document.getElementById('weekly-report')
      const canvas = await html2canvas(reportEl, {
        scale: 2,
        backgroundColor: '#fdf6f2',
        useCORS: true,
        logging: false,
        windowWidth: reportEl.scrollWidth,
      })
      const imgData = canvas.toDataURL('image/png')
      const pdf = new jsPDF({
        orientation: 'portrait',
        unit: 'mm',
        format: 'a4',
      })
      const pdfWidth = pdf.internal.pageSize.getWidth()
      const pdfHeight = pdf.internal.pageSize.getHeight()
      const imgHeightMm = (canvas.height * pdfWidth) / canvas.width

      if (imgHeightMm <= pdfHeight) {
        pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, imgHeightMm)
      } else {
        let yOffset = 0
        while (yOffset < imgHeightMm) {
          if (yOffset > 0) pdf.addPage()
          pdf.addImage(imgData, 'PNG', 0, -yOffset, pdfWidth, imgHeightMm)
          yOffset += pdfHeight
        }
      }

      pdf.save(`CalSnap-Report-${new Date().toISOString().slice(0, 10)}.pdf`)
      setPdfState('done')
      setTimeout(() => setPdfState('idle'), 2500)
    } catch (e) {
      console.error('PDF generation error:', e)
      setPdfState('idle')
    }
  }

  return (
    <div>
      <div id="weekly-report" className={styles.report}>
        {/* Header */}
        <div className={styles.reportHeader}>
          <div className={styles.appLogo}>CalSnap 🌸</div>
          <h2 className={styles.reportTitle}>Weekly Nutrition Report</h2>
          <p className={styles.dateRange}>{weekRange}</p>
        </div>

        {/* Overview */}
        <div className={styles.section}>
          <div className={styles.sectionPill} style={{ background: '#fad4e0', color: '#a0304a' }}>
            🌸 Overview
          </div>
          <p className={styles.overviewText}>{report.overview}</p>
          <div className={styles.dayBadges}>
            <div className={styles.dayBadge} style={{ background: '#d4ecc8', borderColor: '#a8d898' }}>
              <span className={styles.dayBadgeIcon}>✨</span>
              <span className={styles.dayBadgeLabel}>Best Day</span>
              <span className={styles.dayBadgeName}>{report.bestDay?.day || '—'}</span>
              {report.bestDay?.calories > 0 && (
                <span className={styles.dayBadgeKcal}>{report.bestDay.calories} kcal</span>
              )}
            </div>
            <div className={styles.dayBadge} style={{ background: '#fad4e0', borderColor: '#f0a8b8' }}>
              <span className={styles.dayBadgeIcon}>🌿</span>
              <span className={styles.dayBadgeLabel}>Most Calories</span>
              <span className={styles.dayBadgeName}>{report.worstDay?.day || '—'}</span>
              {report.worstDay?.calories > 0 && (
                <span className={styles.dayBadgeKcal}>{report.worstDay.calories} kcal</span>
              )}
            </div>
          </div>
        </div>

        {/* Weekly Bar Chart */}
        <div className={styles.section}>
          <div className={styles.chartMeta}>
            <span className={styles.chartLabel}>Daily Calories</span>
            <span className={styles.avgBadge}>Avg {avgCalories} kcal/day</span>
          </div>
          <ResponsiveContainer width="100%" height={155}>
            <BarChart data={weekData} margin={{ top: 6, right: 4, left: -22, bottom: 0 }}>
              <XAxis dataKey="label" tick={{ fontSize: 11, fill: '#806068' }} axisLine={false} tickLine={false} />
              <YAxis tick={{ fontSize: 10, fill: '#806068' }} axisLine={false} tickLine={false} />
              <Tooltip content={<ChartTooltip />} />
              <ReferenceLine
                y={calorieGoal}
                stroke="#9060c8"
                strokeDasharray="5 3"
                strokeWidth={1.5}
                label={{ value: 'Goal', position: 'insideTopRight', fontSize: 10, fill: '#9060c8' }}
              />
              <Bar dataKey="kcal" radius={[5, 5, 0, 0]}>
                {weekData.map((d, i) => (
                  <Cell key={i} fill={d.kcal > calorieGoal ? '#d4607a' : '#e0789a'} />
                ))}
              </Bar>
            </BarChart>
          </ResponsiveContainer>

          {/* Mini macro table */}
          <div className={styles.macroTableWrap}>
            <table className={styles.macroTable}>
              <thead>
                <tr>
                  <th>Day</th>
                  <th style={{ color: '#d4607a' }}>P (g)</th>
                  <th style={{ color: '#9060c8' }}>C (g)</th>
                  <th style={{ color: '#d07030' }}>F (g)</th>
                </tr>
              </thead>
              <tbody>
                {weekData.map((d, i) => (
                  <tr key={i} className={i % 2 === 0 ? styles.rowEven : ''}>
                    <td className={styles.dayCell}>{d.label}</td>
                    <td>{d.protein}</td>
                    <td>{d.carbs}</td>
                    <td>{d.fat}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        {/* Macro Summary */}
        <div className={styles.section}>
          <div className={styles.sectionPill} style={{ background: '#e4d8f8', color: '#5030a0' }}>
            💪 Macro Summary
          </div>
          <div className={styles.macroRow}>
            <MacroChip
              label="Protein"
              average={avgProtein}
              goal={goals?.protein || 0}
              status={report.macroGaps?.protein}
            />
            <MacroChip
              label="Carbs"
              average={avgCarbs}
              goal={goals?.carbs || 0}
              status={report.macroGaps?.carbs}
            />
            <MacroChip
              label="Fat"
              average={avgFat}
              goal={goals?.fat || 0}
              status={report.macroGaps?.fat}
            />
          </div>
        </div>

        {/* Highlights */}
        {report.highlights?.length > 0 && (
          <div className={styles.section}>
            <div className={styles.sectionPill} style={{ background: '#fad4e0', color: '#a0304a' }}>
              📈 Highlights
            </div>
            <ul className={styles.bulletList}>
              {report.highlights.map((h, i) => (
                <li key={i} className={styles.bulletItem}>
                  <span className={styles.bulletDot} style={{ background: '#e0789a' }} />
                  <span>{h}</span>
                </li>
              ))}
            </ul>
          </div>
        )}

        {/* Areas to Improve */}
        {report.improvements?.length > 0 && (
          <div className={styles.section}>
            <div className={styles.sectionPill} style={{ background: '#e4d8f8', color: '#5030a0' }}>
              ⚠️ Areas to Improve
            </div>
            <ul className={styles.bulletList}>
              {report.improvements.map((imp, i) => (
                <li key={i} className={styles.bulletItem}>
                  <span className={styles.bulletDot} style={{ background: '#9060c8' }} />
                  <span>{imp}</span>
                </li>
              ))}
            </ul>
          </div>
        )}

        {/* Next Week Goal */}
        {report.nextWeekGoal && (
          <div className={styles.section}>
            <div className={styles.sectionPill} style={{ background: '#d4ecc8', color: '#205020' }}>
              🎯 Next Week Goal
            </div>
            <p className={styles.goalText}>{report.nextWeekGoal}</p>
          </div>
        )}

        {/* Footer */}
        <div className={styles.reportFooter}>
          Generated by CalSnap 🌸 · {todayStr}
        </div>
      </div>

      {/* Download button — outside report div, not captured in PDF */}
      <button
        className={styles.downloadBtn}
        onClick={downloadPDF}
        disabled={pdfState === 'loading'}
        data-state={pdfState}
      >
        {pdfState === 'loading'
          ? 'Generating PDF...'
          : pdfState === 'done'
          ? '✓ Downloaded!'
          : '⬇ Download PDF Report'}
      </button>
    </div>
  )
}

