const downloadPDF = async () => {
  setPdfState('loading')
  const reportEl = document.getElementById('weekly-report')
  try {
    reportEl.classList.add(styles.reportPdfMode)
    await new Promise(r => requestAnimationFrame(r))

    const canvas = await html2canvas(reportEl, {
      scale: 2,
      backgroundColor: '#fdf6f2',
      useCORS: true,
      logging: false,
      windowWidth: 800,
      scrollY: 0,
    })

    reportEl.classList.remove(styles.reportPdfMode)

    const imgData = canvas.toDataURL('image/png')
    const pdf = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' })

    const pageWidth = pdf.internal.pageSize.getWidth()
    const pageHeight = pdf.internal.pageSize.getHeight()
    const margin = 10
    const usableWidth = pageWidth - margin * 2
    const imgHeightMm = (canvas.height * usableWidth) / canvas.width

    if (imgHeightMm <= pageHeight - margin * 2) {
      const yOffset = (pageHeight - imgHeightMm) / 2
      pdf.addImage(imgData, 'PNG', margin, yOffset, usableWidth, imgHeightMm)
    } else {
      const scaleFactor = (pageHeight * 2 - margin * 4) / imgHeightMm
      const scaledWidth = usableWidth * scaleFactor
      const scaledHeight = imgHeightMm * scaleFactor
      const xOffset = (pageWidth - scaledWidth) / 2

      if (scaledHeight <= pageHeight - margin * 2) {
        pdf.addImage(imgData, 'PNG', xOffset, margin, scaledWidth, scaledHeight)
      } else {
        pdf.addImage(imgData, 'PNG', margin, margin, usableWidth, imgHeightMm)
        const page1Height = pageHeight - margin * 2
        pdf.addPage()
        pdf.addImage(imgData, 'PNG', margin, margin - page1Height, usableWidth, imgHeightMm)
      }
    }

    pdf.save(`CalSnap-Report-${new Date().toISOString().slice(0, 10)}.pdf`)
    setPdfState('done')
    setTimeout(() => setPdfState('idle'), 2500)
  } catch (e) {
    console.error('PDF generation error:', e)
    reportEl?.classList.remove(styles.reportPdfMode)
    setPdfState('idle')
  }
}

