  width: '100%',
  marginTop: '12px',
  padding: '10px',
  background: 'transparent',
  border: '1px solid #e8a0b8',
  borderRadius: '12px',
  color: '#c97a90',
  cursor: 'pointer',
  fontSize: '13px',
  fontWeight: '500',
}

export default function WeeklyReport({ report, weekData, calorieGoal, goals }) {
